<?php
namespace App\Http\Controllers;
use App\Models\Table; use Illuminate\Http\Request; use Illuminate\Support\Str;
class TableController extends Controller { public function index(Request $r){return response()->json(['data'=>Table::where('restaurant_id',$r->user()->restaurant_id)->latest()->get()]);} public function store(Request $r){$d=$r->validate(['label'=>'required|string|max:100','seats'=>'required|integer|min:1|max:100']);$d['restaurant_id']=$r->user()->restaurant_id;$d['code']=Str::upper(Str::random(12));return response()->json(['data'=>Table::create($d)],201);} public function update(Request $r,int $id){$t=Table::where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id);$t->update($r->validate(['label'=>'required|string|max:100','seats'=>'required|integer|min:1|max:100','is_active'=>'sometimes|boolean']));return response()->json(['data'=>$t]);} public function destroy(Request $r,int $id){Table::where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id)->delete();return response()->json(['message'=>'تم حذف الطاولة بنجاح']);} public function status(Request $r,int $id){$t=Table::where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id);$occupied=$t->sessions()->where('status','!=','Closed')->exists();return response()->json(['data'=>['status'=>$occupied?'Occupied':'Available','table'=>$t]]);}}
